from .errors import MissingField, BadType, BadValue


def _type_ok(value, expected):
    types = expected if isinstance(expected, tuple) else (expected,)
    if not isinstance(value, types):
        return False
    if isinstance(value, bool) and bool not in types:
        return False
    return True


def validate(obj, schema):
    result = {}
    for name, spec in schema.items():
        required = spec.get("required", False)
        if name not in obj:
            if required:
                raise MissingField(f"Missing required field: {name!r}")
            result[name] = spec.get("default")
        else:
            value = obj[name]
            if not _type_ok(value, spec["type"]):
                raise BadType(
                    f"Field {name!r}: expected {spec['type']}, got {type(value).__name__}"
                )
            if "choices" in spec and value not in spec["choices"]:
                raise BadValue(
                    f"Field {name!r}: {value!r} not in choices {spec['choices']!r}"
                )
            result[name] = value
    return result

